from common import *
def sc(lbl,v,sub,icn,hl=False):
    st='border:2px solid var(--primary);' if hl else ''
    return f'<div class="card" style="padding:20px;{st}"><div class="row small muted" style="gap:6px">{ic(icn,16)}{lbl}</div><div class="price" style="font-size:34px;margin-top:6px">{v}</div><div class="small muted" style="margin-top:4px">{sub}</div></div>'
cards=f'<div class="grid" style="grid-template-columns:repeat(3,1fr);gap:20px">{sc("Saldo total","R$ 20.000,00","Tudo o que você depositou, menos arremates pagos","wallet")}{sc("Comprometido","R$ 13.000,00","Reservado nos lotes em que você lidera","lock")}{sc("Disponível","R$ 7.000,00","Total − comprometido · usado para novos lances","circle-check",True)}</div>'
expl=f'<div class="alert a-info" style="margin-top:16px">{ic("info",18)}<div><b>Como funciona o comprometido</b>Ao liderar um lote, o valor integral do seu lance fica reservado. Se alguém cobrir, ele volta na hora ao disponível. Ao arrematar, é debitado do total.</div></div>'
lead=''.join(f'<tr><td><div class="row" style="gap:10px">{img(k,"",44).replace("width:100%","").replace("class=\"art ","style=\"width:44px;height:44px;border-radius:4px\" class=\"art ")}<div><b>{IMG[k][1]}</b><div class="xs muted">Lote {l}</div></div></div></td><td><span class="badge b-ok">{ic("trophy",12)}Liderando</span></td><td class="num" style="text-align:right;font-weight:600">{v}</td><td style="text-align:right"><span class="btn g sm">Abrir sala{ic("chevron-right",14)}</span></td></tr>' for k,l,v in [('socr','0007','R$ 12.900,00'),('charp','0009','R$ 100,00')])
lead=lead.replace('R$ 100,00','R$ 100,00')
leadc=f'<div class="card" style="padding:20px"><div class="row" style="justify-content:space-between;margin-bottom:8px"><h3 class="serif" style="font-size:18px">Onde seu saldo está comprometido</h3><span class="small muted">2 lotes</span></div><table><tr><th>Lote</th><th>Situação</th><th style="text-align:right">Comprometido</th><th></th></tr>{lead}</table></div>'
mov=''.join(f'<tr><td class="num muted">{d}</td><td>{a}</td><td class="num" style="text-align:right;font-weight:600;color:{c}">{v}</td></tr>' for d,a,v,c in [('23/10 14:31','Lance comprometido · Lote 0007','− R$ 12.900,00 disp.','var(--ink)'),('23/10 14:20','Liberado (superado) · Lote 0007','+ R$ 11.900,00 disp.','var(--ok)'),('23/10 11:02','Lance comprometido · Lote 0009','− R$ 100,00 disp.','var(--ink)'),('23/10 09:15','Depósito simulado','+ R$ 20.000,00','var(--ok)')])
movc=f'<div class="card" style="padding:20px"><h3 class="serif" style="font-size:18px;margin-bottom:8px">Movimentações</h3><table><tr><th>Data (BRT)</th><th>Descrição</th><th style="text-align:right">Valor</th></tr>{mov}</table></div>'
def dep(val='5.000,00',err=None,btn='Adicionar R$ 5.000,00',pend=False):
    e=f'<div class="help e">{ic("circle-alert",14)}<span>{err}</span></div>' if err else '<div class="help">Entre R$ 1,00 e R$ 100.000,00 por depósito</div>'
    chips=''.join(f'<span class="btn o sm num" style="flex:1">{x}</span>' for x in ['R$ 1.000','R$ 5.000','R$ 10.000'])
    b=f'<span class="btn p lg" style="width:100%;margin-top:14px">{ic("loader-circle",18)}Adicionando…</span>' if pend else f'<span class="btn p lg" style="width:100%;margin-top:14px">{ic("plus",18)}{btn}</span>'
    return f'''<div class="card" style="padding:20px"><div class="row" style="justify-content:space-between"><h3 class="serif" style="font-size:18px">Adicionar saldo</h3><span class="sim">Simulado</span></div><p class="small muted" style="margin:6px 0 14px">Dinheiro fictício para a demonstração. Sem Pix, cartão ou dados bancários.</p><span class="lbl">Valor (R$)</span><div class="input {"err" if err else ""}" style="height:48px"><span class="muted">R$</span><b class="num" style="font-size:17px">{val}</b></div>{e}<div class="row" style="gap:8px;margin-top:10px">{chips}</div>{b}</div>'''
desk=f'''<div class="frame" style="width:1440px">{header('Carteira')}<div style="padding:32px 40px 8px"><h1 class="serif" style="font-size:36px;font-weight:600">Minha carteira</h1><p class="muted">Saldo simulado do Licitante Âmbar-47 · atualizado em tempo real</p></div>
<div style="display:grid;grid-template-columns:8fr 4fr;gap:24px;padding:16px 40px 40px"><div class="col" style="gap:20px"><div>{cards}{expl}</div>{leadc}{movc}</div><div class="col" style="gap:20px">{dep()}</div></div>{foot()}</div>'''
def st(code,name,inner,note=''):
    return f'<div><div class="flabel"><b>{code}</b>{name}</div><div class="frame" style="padding:18px;border-radius:12px">{inner}</div>{f"<div class=note>{note}</div>" if note else ""}</div>'
zero=f'<div class="grid" style="grid-template-columns:repeat(3,1fr);gap:10px">'+''.join(f'<div class="card" style="padding:14px"><div class="xs muted">{a}</div><div class="price" style="font-size:22px">R$ 0,00</div></div>' for a in ['Total','Comprometido','Disponível'])+f'</div><div style="text-align:center;padding:18px 0 4px">{ic("wallet",28)}<h3 class="serif" style="font-size:18px;margin-top:6px">Você ainda não tem saldo</h3><p class="small muted" style="margin:4px 0 12px">Adicione um valor simulado para começar a dar lances.</p><span class="btn p">{ic("plus",16)}Adicionar saldo simulado</span></div>'
dlg=f'''<div style="position:relative;height:300px;border-radius:10px;overflow:hidden;background:var(--bg)"><div class="overlay"><div class="dialog" style="width:380px"><h3 class="serif" style="font-size:20px">Adicionar R$ 5.000,00?</h3><p class="small muted" style="margin:8px 0 12px">Saldo simulado, sem valor real. Disponível passa de R$ 7.000,00 para R$ 12.000,00.</p><div class="row" style="justify-content:flex-end"><span class="btn g">Voltar</span><span class="btn p">Confirmar depósito</span></div></div></div></div>'''
S=[st('E2','Saldo zero',zero),
st('E3','Depósito inválido',dep('0,50','Valor mínimo R$ 1,00. Use números, ex.: 1.500 ou 1500,00.','Adicionar'),'Postel: aceita “1.500”, “1500,00”, “R$ 1500”.'),
st('E4','Confirmação (AlertDialog)',dlg,'Chave de idempotência por envio: repetir não duplica (briefing §6).'),
st('E5','Pendente',dep(pend=True),'Números não animam antes da confirmação real.'),
st('E6','Sucesso',f'<div class="alert a-ok">{ic("circle-check",18)}<div><b>Depósito simulado confirmado</b>+ R$ 5.000,00 · Disponível agora R$ 12.000,00.</div></div><div class="card row" style="padding:12px 14px;margin-top:12px;box-shadow:var(--sh-lg)">{ic("circle-check",18)}<b class="small">Toast: Saldo atualizado</b></div>'),
st('E7','Erro / confirmação indeterminada',f'<div class="col" style="gap:10px"><div class="alert a-err">{ic("circle-alert",18)}<div><b>Não foi possível adicionar saldo</b>Nada foi alterado. Tente novamente.</div></div><div class="alert a-info">{ic("info",18)}<div><b>Não conseguimos confirmar o depósito</b>Atualize a carteira antes de tentar de novo; repetir não duplica o valor.<div style="margin-top:8px"><span class="btn o sm">{ic("refresh-cw",14)}Atualizar carteira</span></div></div></div></div>'),
st('E8','Superado em tempo real (R21)',f'<div class="alert a-ok">{ic("trending-up",18)}<div><b>Você foi superado em “Sob a onda em Kanagawa”</b>R$ 4.200,00 voltou ao disponível.</div></div><div class="grid" style="grid-template-columns:1fr 1fr;gap:10px;margin-top:12px"><div class="card" style="padding:12px"><div class="xs muted">Comprometido</div><div class="price" style="font-size:20px">R$ 13.000,00</div><div class="xs" style="color:var(--ok)">− R$ 4.200,00</div></div><div class="card" style="padding:12px"><div class="xs muted">Disponível</div><div class="price" style="font-size:20px">R$ 7.000,00</div><div class="xs" style="color:var(--ok)">+ R$ 4.200,00</div></div></div>','Destaque breve (2 s), sem animação com reduced-motion.'),
st('E9','Após arremate (R24)',f'<div class="alert a-info">{ic("trophy",18)}<div><b>Arremate liquidado · Lote 0007</b>R$ 12.900,00 saiu do comprometido e foi debitado do total. <u>Ver comprovante</u></div></div>'),
st('E10','Carregando',f'<div class="grid" style="grid-template-columns:repeat(3,1fr);gap:10px">'+''.join('<div class="card" style="padding:14px"><div class="sk" style="height:10px;width:60%"></div><div class="sk" style="height:24px;width:90%;margin-top:10px"></div></div>' for _ in range(3))+'</div><div class="sk" style="height:120px;margin-top:12px;border-radius:10px"></div>')]
body=f'''<div class="board">{boardhead('Carteira · desktop 1440','R12/R20–R22: total, comprometido e disponível + depósito simulado. Lei de Miller: 3 números, disponível em destaque.')}
<div class="flabel"><b>E1</b>Com saldo e compromissos</div>{desk}<div class="grid" style="grid-template-columns:repeat(3,1fr);margin-top:28px;align-items:start">{"".join(S)}</div></div>'''
save('06-carteira-desktop',page('Carteira desktop',body,1520))
# mobile
mt=mheader('Minha carteira',True)
msc=lambda a,v,s,hl=False: f'<div class="card" style="padding:14px;{"border:2px solid var(--primary);" if hl else ""}"><div class="row" style="justify-content:space-between"><span class="small muted">{a}</span><span class="price" style="font-size:22px">{v}</span></div><div class="xs muted">{s}</div></div>'
mcards=f'<div class="col" style="gap:10px;padding:16px">{msc("Disponível","R$ 7.000,00","Para novos lances",True)}{msc("Comprometido","R$ 13.000,00","Em 2 lotes que você lidera")}{msc("Saldo total","R$ 20.000,00","Disponível + comprometido")}</div>'
mlead='<div style="padding:0 16px"><h3 class="serif" style="font-size:17px;margin-bottom:4px">Comprometido em</h3>'+''.join(f'<div class="kv" style="padding:10px 0;border-bottom:1px solid var(--border)"><span>{t}<br><span class="xs">Lote {l} · liderando</span></span><b class="num">{v}</b></div>' for t,l,v in [('A morte de Sócrates','0007','R$ 12.900,00'),('Madame Georges Charpentier…','0009','R$ 100,00')])+'</div>'
mbar=f'<div class="mbar"><span class="btn p lg" style="width:100%">{ic("plus",18)}Adicionar saldo simulado</span></div>'
m1=mt+mcards+mlead+mbar
sheet=lambda inner: f'<div style="position:absolute;inset:0;background:rgba(31,27,22,.45)"></div><div style="position:absolute;left:0;right:0;bottom:0;background:var(--surface);border-radius:18px 18px 0 0;padding:20px 16px 28px;box-shadow:var(--sh-lg)"><div style="width:40px;height:4px;background:var(--border);border-radius:4px;margin:0 auto 14px"></div>{inner}</div>'
dm=lambda val,err=None,pend=False: f'<div class="row" style="justify-content:space-between"><h3 class="serif" style="font-size:20px">Adicionar saldo</h3><span class="sim">Simulado</span></div><p class="small muted" style="margin:6px 0 12px">Sem Pix, cartão ou dados bancários.</p><span class="lbl">Valor (R$)</span><div class="input {"err" if err else ""}" style="height:48px"><span class="muted">R$</span><b class="num">{val}</b></div>'+(f'<div class="help e">{ic("circle-alert",14)}<span>{err}</span></div>' if err else '<div class="help">Entre R$ 1,00 e R$ 100.000,00</div>')+'<div class="row" style="gap:8px;margin-top:10px">'+''.join(f'<span class="btn o sm num" style="flex:1">{x}</span>' for x in ['R$ 1.000','R$ 5.000','R$ 10.000'])+'</div>'+(f'<span class="btn p lg" style="width:100%;margin-top:14px">{ic("loader-circle",18)}Adicionando…</span>' if pend else f'<span class="btn p lg dis" style="width:100%;margin-top:14px">Corrija o valor</span>' if err else f'<span class="btn p lg" style="width:100%;margin-top:14px">{ic("plus",18)}Adicionar R$ {val}</span>')+'<span class="btn g" style="width:100%;margin-top:6px">Cancelar</span>'
m2=mt+mcards+sheet(dm('5.000,00'))
m3=mt+mcards+sheet(dm('0,50','Valor mínimo R$ 1,00.'))
m4=mt+f'<div class="alert a-ok" style="margin:16px 16px 0">{ic("circle-check",18)}<div><b>Depósito simulado confirmado</b>+ R$ 5.000,00</div></div>'+mcards.replace('R$ 7.000,00','R$ 12.000,00').replace('R$ 20.000,00','R$ 25.000,00')+mlead+mbar
m5=mt+'<div class="col" style="gap:10px;padding:16px">'+''.join(f'<div class="card" style="padding:14px"><div class="row" style="justify-content:space-between"><span class="small muted">{a}</span><span class="price" style="font-size:22px">R$ 0,00</span></div></div>' for a in ['Disponível','Comprometido','Saldo total'])+f'</div><div style="text-align:center;padding:30px 24px">{ic("wallet",30)}<h3 class="serif" style="font-size:19px;margin-top:8px">Você ainda não tem saldo</h3><p class="small muted" style="margin-top:4px">Adicione um valor simulado para dar lances.</p></div>'+mbar
def mf(l,inner,h=844):
    return f'<div><div class="flabel"><b>{l[0]}</b>{l[1]}</div><div class="frame" style="width:390px;height:{h}px;border-radius:24px">{inner}</div></div>'
body=f'''<div class="board">{boardhead('Carteira · mobile 390','Disponível primeiro (é o número que decide o lance). Depósito em Sheet inferior; CTA fixo ao alcance do polegar.')}
<div class="row" style="gap:28px;align-items:flex-start">{mf(('M1','Com saldo'),m1)}{mf(('M2','Depósito (Sheet)'),m2)}{mf(('M3','Valor inválido'),m3)}{mf(('M4','Sucesso'),m4)}{mf(('M5','Saldo zero'),m5)}</div></div>'''
save('07-carteira-mobile',page('Carteira mobile',body,2200))
